mapper.sql:
EXISTS (SELECT 1 FROM merchant_store s JOIN sys_user u ON u.id=#{userId} AND u.tenant_id=#{tenantId} AND u.status='ACTIVE' AND u.deleted=0
  WHERE s.id=o.store_id AND s.tenant_id=#{tenantId} AND s.status='ACTIVE' AND s.deleted=0
  AND (EXISTS (SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id
        WHERE ur.tenant_id=#{tenantId} AND ur.user_id=#{userId} AND r.tenant_id=#{tenantId}
          AND r.role_scope='TENANT' AND r.status='ACTIVE' AND r.deleted=0
          AND r.role_code IN ('MERCHANT_ADMIN','FINANCE_OPERATOR','WAREHOUSE_OPERATOR','CUSTOMER_SERVICE_OPERATOR'))
    OR (EXISTS (SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id
        WHERE ur.tenant_id=#{tenantId} AND ur.user_id=#{userId} AND r.tenant_id=#{tenantId}
          AND r.role_code='MERCHANT_OPERATOR' AND r.role_scope='TENANT' AND r.status='ACTIVE' AND r.deleted=0)
      AND EXISTS (SELECT 1 FROM sys_user_store_scope uss WHERE uss.tenant_id=#{tenantId}
        AND uss.user_id=#{userId} AND uss.store_id=o.store_id AND uss.status='ACTIVE')))
)

mapper.update:
UPDATE exception_case SET assigned_to_user_id=#{assignedToUserId},responsible_party=#{responsibleParty},
    status=CASE WHEN status='OPEN' THEN 'PROCESSING' ELSE status END,version=version+1
    WHERE tenant_id=#{tenantId} AND id=#{exceptionId} AND status <> 'CLOSED' AND version=#{version}
